// The plan, in one of two package modes (#158). Embedded: the .incbin stub
// or the decimal TU defines these as the plan bytes and their count. Disk:
// build.sh's two-line TU defines the count as 0, and the plan is the file
// update_plan.seeu beside this executable (or whatever --plan names),
// mapped at start-up and validated exactly as an embedded plan is.
extern const unsigned char kSeemlUpdatePlan[];
extern const size_t kSeemlUpdatePlanSize;

namespace {

// Cooperative cancellation (#202 item 1). The handler only stores to a
// lock-free atomic — the one thing a signal handler may safely do — and the
// engine polls it once per step through TrainOptions::should_stop. The run
// then stops at the step boundary, checkpoints there (--checkpoint) and
// exits 5. SA_RESETHAND makes a second signal the default action, so a run
// stuck in a long step or evaluation still dies on a second Ctrl-C;
// SA_RESTART keeps a signal landing in a read or a checkpoint write from
// turning into a spurious I/O failure.
std::atomic<bool> g_stop_requested{false};
static_assert(std::atomic<bool>::is_always_lock_free);
int g_stop_signal = 0;  // written before the store, read after the load

extern "C" void OnStopSignal(int sig) {
  g_stop_signal = sig;
  g_stop_requested.store(true, std::memory_order_release);
}

void InstallStopHandlers() {
#if defined(_WIN32)
  std::signal(SIGINT, OnStopSignal);
  std::signal(SIGTERM, OnStopSignal);
#else
  struct sigaction sa {};
  sa.sa_handler = OnStopSignal;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = SA_RESTART | SA_RESETHAND;
  sigaction(SIGINT, &sa, nullptr);
  sigaction(SIGTERM, &sa, nullptr);
#endif
}

constexpr const char* kPlanFileName = "update_plan.seeu";
// The target's peak in GFLOP/s, as the compile was told it
// (--peak-gflops; written here by the emitter, 0 = unstated): the runtime
// screen's predicted step and utilization are computed against it, and a
// run's own --peak-gflops overrides it (S0 #146).
constexpr double kSeemlPeakGflops = 0.0 /*seeml:peak_gflops*/;
// The target GPU's peak (--gpu-peak-gflops at compile time, S6 #152): the
// denominator of the predicted step when the run is on the Metal backend.
constexpr double kSeemlGpuPeakGflops = 0.0 /*seeml:gpu_peak_gflops*/;

/// The directory holding this executable, asked of the OS (a bare or
/// PATH-found argv[0] says nothing about where the binary is), with
/// symlinks resolved; argv[0]'s directory, then ".", when the OS cannot say.
std::string ExecutableDir(const char* argv0) {
  std::string exe;
#if defined(__APPLE__)
  uint32_t n = 0;
  _NSGetExecutablePath(nullptr, &n);
  if (n > 0) {
    std::string buf(n, '\0');
    if (_NSGetExecutablePath(buf.data(), &n) == 0) exe.assign(buf.c_str());
  }
#elif defined(__linux__)
  char buf[PATH_MAX];
  const ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
  if (n > 0) exe.assign(buf, static_cast<size_t>(n));
#endif
  if (exe.empty() && argv0 && *argv0) exe = argv0;
#if defined(__unix__) || defined(__APPLE__)
  if (!exe.empty()) {
    char real[PATH_MAX];
    if (realpath(exe.c_str(), real)) exe = real;
  }
#endif
  const size_t slash = exe.find_last_of("/\\");
  if (slash == std::string::npos) return ".";
  if (slash == 0) return "/";
  return exe.substr(0, slash);
}

const char* Arg(int argc, char** argv, const char* flag, const char* dflt) {
  for (int i = 1; i + 1 < argc; ++i)
    if (std::strcmp(argv[i], flag) == 0) return argv[i + 1];
  return dflt;
}

bool Has(int argc, char** argv, const char* flag) {
  for (int i = 1; i < argc; ++i)
    if (std::strcmp(argv[i], flag) == 0) return true;
  return false;
}

// Digits only (S4 #150, review F63): strtoull skips leading whitespace and
// negates a "-1" behind it, which is how `--steps " -1"` parsed.
bool ParseU64(const char* s, uint64_t* out) {
  return seeml::update::recipe::ParseU64Strict(s, out);
}

// A finite decimal, consumed completely (S4 #150): strtod skips leading
// whitespace and takes hex floats, "nan" and "inf".
bool ParseF64(const char* s, double* out) {
  return seeml::update::recipe::ParseF64Strict(s, out);
}

constexpr const char* kUsage =
    "usage: model_update --model <source.smf> --data <corpus.sds|text.txt|docs.jsonl>"
    " [--out updated.smf] [--steps N] [--seed S]"
    " [--val-frac F] [--checkpoint ckpt] [--checkpoint-every N]"
    " [--resume] [--loss-log curve.csv] [--backend cpu|metal|auto]"
    " [--min-improvement F] [--require-accuracy] [--report report.json]"
    " [--eval-every N] [--patience K] [--plan update_plan.seeu]"
    " [--force] [--peak-gflops G] [--threads N] [--help]\n"
    "  --threads N: the worker-pool width (default: $SEEML_THREADS, else\n"
    "  the hardware's); 1 runs serially. A throughput knob only: every\n"
    "  width computes the same bits.\n"
    "  --data: a pre-tokenized corpus (.sds), or raw text ingested on the\n"
    "  device with the model's own tokenizer section (which must be the\n"
    "  plan's): a .txt is one document, a .jsonl one {\"text\"} or\n"
    "  {\"prompt\", \"response\"} per line. The run is the run on the SDS\n"
    "  the compiler would write from the same text.\n"
    "  --peak-gflops G: the target's peak in GFLOP/s, for the runtime\n"
    "  screen's predicted step and utilization (default: the compile's).\n"
    "  --plan FILE: the update plan to run. A package built without an\n"
    "  embedded plan reads update_plan.seeu beside this executable; --plan\n"
    "  names another file (and overrides an embedded plan). Either way the\n"
    "  plan is validated in full — version, seal, source-model hash.\n"
    "  --eval-every N: with a validation split, evaluate every N steps and\n"
    "  commit the BEST evaluated state, not the last (default: steps/10,\n"
    "  at least 1; 0 evaluates only before and after and commits the last).\n"
    "  --patience K: stop after K consecutive evaluations without a new best\n"
    "  (default 0: never).\n"
    "  --min-improvement F: commit only if the gated loss fell by at least\n"
    "  the fraction F of its initial value (default 0: any strict fall).\n"
    "  --require-accuracy: additionally require held-out accuracy not to\n"
    "  drop (class-label plans with a validation split only).\n"
    "  --report FILE: write the backend, the gate parameters, the loss and\n"
    "  accuracy pairs and the verdict as JSON.\n"
    "  --backend: the executor (default cpu, or $SEEML_BACKEND). cpu is the\n"
    "  bitwise-deterministic reference and builds anywhere; metal runs the\n"
    "  update on an Apple GPU (an error where none exists); auto takes the\n"
    "  GPU when present and says so, else cpu.\n"
    "  exit codes: 0 committed; 1 failed (the model untouched); 2 usage;\n"
    "  3 rejected by the gate (the model untouched); 4 committed, but\n"
    "  --report or --loss-log could not be written; 5 stopped by SIGINT or\n"
    "  SIGTERM at a step boundary (the model untouched; with --checkpoint the\n"
    "  stop is checkpointed and --resume finishes the run).\n";

/// Every argv slot must be a known flag or a known flag's value: the
/// compiler CLI treats unconsumed arguments as hard errors, and the device
/// runner follows the same rule — a typo'd --val-frc must not silently
/// train with the default.
bool ArgsOk(int argc, char** argv) {
  static const char* const kValueFlags[] = {
      "--model",      "--data",     "--out",
      "--steps",      "--seed",     "--val-frac",
      "--checkpoint", "--loss-log", "--checkpoint-every",
      "--backend",    "--min-improvement", "--report",
      "--eval-every", "--patience", "--plan", "--peak-gflops", "--threads"};
  static const char* const kBoolFlags[] = {"--force", "--resume", "--help",
                                           "-h", "--require-accuracy"};
  for (int i = 1; i < argc; ++i) {
    // Empty argv slots are shell debris (a quoted-but-unset "$VAR"), not
    // typos: nothing can be misread from one, and the pre-strict runner
    // accepted them — rejecting them would break existing wrappers for
    // zero safety gain. They stay ignorable.
    if (argv[i][0] == '\0') continue;
    bool known = false;
    for (const char* f : kValueFlags) {
      if (std::strcmp(argv[i], f) != 0) continue;
      // A '-'-prefixed value is a flag that swallowed its neighbor
      // (`--out --force`), not a value: Arg() would take it as a filename
      // while Has() independently still sees it as set. No legitimate
      // value here starts with '-' (paths aside, and steps/seed/val-frac
      // reject negatives anyway), so refuse rather than double-read.
      if (i + 1 >= argc || argv[i + 1][0] == '-') {
        std::fprintf(stderr, "model_update: %s requires a value\n", argv[i]);
        return false;
      }
      known = true;
      ++i;
      break;
    }
    if (!known)
      for (const char* f : kBoolFlags)
        if (std::strcmp(argv[i], f) == 0) {
          known = true;
          break;
        }
    if (!known) {
      std::fprintf(stderr,
                   "model_update: unknown argument '%s' (see --help)\n",
                   argv[i]);
      return false;
    }
  }
  return true;
}

/// The --data file's extension, lowercased ("" when it has none).
std::string DataExtension(const std::string& path) {
  const size_t slash = path.find_last_of("/\\");
  const size_t dot = path.find_last_of('.');
  if (dot == std::string::npos || (slash != std::string::npos && dot < slash))
    return "";
  std::string ext = path.substr(dot + 1);
  for (char& c : ext) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
  return ext;
}

/// Raw text on the device (#202 item 2): a .txt (one document) or a .jsonl
/// (one {"text"} or {"prompt", "response"} per line) through the vendored
/// ingest — sanitize, deduplicate, encode, pack — with the model's own
/// tokenizer section, which must be the one the plan was compiled with. The
/// dataset is the one the canonical SDS of that ingest loads as: the same
/// records, the same mask, the same content hash (a plan compiled from the
/// same text pins exactly that hash), so the run is the SDS run.
std::expected<seeml::update_rt::Dataset, std::string> LoadRawText(
    const std::string& model_path, const std::string& data_path,
    const std::string& ext, const seeml::update::PlanHeader& header) {
  namespace tk = seeml::tokenizer;
  if (header.input_kind != 1)
    return std::unexpected(
        "a feature plan takes no raw text: --data needs its pre-tokenized .sds");
  if (header.tokenizer_hash == 0)
    return std::unexpected(
        "the plan names no tokenizer: raw text needs a model exported with "
        "its tokenizer section (or pass the pre-tokenized .sds)");
  std::ifstream model(model_path, std::ios::binary);
  if (!model) return std::unexpected("cannot open --model '" + model_path + "'");
  model.seekg(0, std::ios::end);
  const std::streamoff end = model.tellg();
  if (end <= 0) return std::unexpected("cannot size --model '" + model_path + "'");
  const uint64_t model_size = static_cast<uint64_t>(end);
  std::vector<uint8_t> prefix(static_cast<size_t>(
      std::min<uint64_t>(model_size, seeml::update::kSmfPreambleMaxBytes)));
  model.seekg(0);
  if (!model.read(reinterpret_cast<char*>(prefix.data()),
                  static_cast<std::streamsize>(prefix.size())))
    return std::unexpected("cannot read --model '" + model_path + "'");
  auto pre = seeml::update::ReadSmfPreamble(prefix.data(), prefix.size(),
                                            model_size);
  if (!pre) return std::unexpected("--model '" + model_path + "': " + pre.error());
  if (pre->tokenizer_size == 0)
    return std::unexpected("--model '" + model_path +
                           "' carries no tokenizer section: raw text needs one");
  std::vector<uint8_t> section(static_cast<size_t>(pre->tokenizer_size));
  model.seekg(static_cast<std::streamoff>(pre->tokenizer_offset));
  if (!model.read(reinterpret_cast<char*>(section.data()),
                  static_cast<std::streamsize>(section.size())))
    return std::unexpected("cannot read the tokenizer section of '" +
                           model_path + "'");
  const uint64_t tokenizer_hash =
      seeml::update::ContentHash64(section.data(), section.size());
  if (tokenizer_hash != header.tokenizer_hash) {
    char buf[160];
    std::snprintf(buf, sizeof buf,
                  "the model's tokenizer section (%016llx) is not the one the "
                  "plan was compiled with (%016llx)",
                  (unsigned long long)tokenizer_hash,
                  (unsigned long long)header.tokenizer_hash);
    return std::unexpected(std::string(buf));
  }
  auto tok = tk::ByteLevelBpe::Load(section);
  if (!tok) return std::unexpected("tokenizer section: " + tok.error());

  std::ifstream in(data_path, std::ios::binary);
  if (!in) return std::unexpected("cannot open --data '" + data_path + "'");
  std::string text((std::istreambuf_iterator<char>(in)),
                   std::istreambuf_iterator<char>());
  if (in.bad()) return std::unexpected("cannot read --data '" + data_path + "'");
  std::vector<tk::Document> documents;
  tk::IngestOptions options;
  options.seq_len = header.seq_len;
  if (ext == "txt") {
    options.one_document = true;
    documents.push_back({std::move(text), {}, false});
  } else {
    auto docs = tk::DocumentsFromJsonl(text);
    if (!docs) return std::unexpected(data_path + ": " + docs.error());
    documents = std::move(*docs);
  }
  auto ingest = tk::Ingest(*tok, tokenizer_hash, documents, options);
  if (!ingest) return std::unexpected(ingest.error());
  const tk::IngestManifest& m = ingest->manifest;
  std::fprintf(stderr,
               "seeml-update: ingested '%s': %llu of %llu document(s) kept "
               "(%llu empty, %llu duplicate, %llu degenerate dropped); %llu "
               "window(s) of %llu, %llu remainder token(s) dropped; corpus "
               "%016llx\n",
               data_path.c_str(), (unsigned long long)m.documents_kept,
               (unsigned long long)m.documents_in,
               (unsigned long long)m.dropped_empty,
               (unsigned long long)m.dropped_duplicate,
               (unsigned long long)m.dropped_degenerate,
               (unsigned long long)m.windows,
               (unsigned long long)header.seq_len,
               (unsigned long long)m.remainder_tokens,
               (unsigned long long)ingest->corpus_hash);
  auto ds = seeml::update_rt::Dataset::FromTokens(
      std::move(ingest->ids), m.windows, header.seq_len,
      std::move(ingest->mask), tokenizer_hash);
  if (!ds) return std::unexpected(ds.error());
  ds->set_content_hash(ingest->corpus_hash);
  return std::move(*ds);
}

}  // namespace

int main(int argc, char** argv) {
  // Tier D (docs/benchmarks.md, F9 #140): where the update's wall goes.
  // Clocks sit between phases, never inside a step.
  const auto t_main0 = std::chrono::steady_clock::now();
  auto since = [](std::chrono::steady_clock::time_point a) {
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - a)
        .count();
  };
  // Strictness before convenience: ArgsOk first, so `--out -h` is a
  // missing-value error rather than a help hit on a swallowed slot. After
  // it passes, every argv slot is a known flag or a non-flag value, and
  // Has()/Arg() below cannot double-read a slot.
  if (!ArgsOk(argc, argv)) return 2;
  if (Has(argc, argv, "--help") || Has(argc, argv, "-h")) {
    std::fputs(kUsage, stdout);
    return 0;
  }

  const std::string model = Arg(argc, argv, "--model", "");
  const std::string data = Arg(argc, argv, "--data", "");
  const std::string out = Arg(argc, argv, "--out", "updated_model.smf");
  const std::string loss_log = Arg(argc, argv, "--loss-log", "");
  const bool force = Has(argc, argv, "--force");

  uint64_t steps = 0, seed = 0;
  double val_frac = 0.1, min_improvement = 0.0;
  // The negated in-range form rejects NaN, which `< 0.0 || >= 1.0` lets
  // through — and a NaN val_frac silently disables the validation gate
  // (a NaN margin would silently pass it).
  if (!ParseU64(Arg(argc, argv, "--steps", "0"), &steps) ||
      !ParseU64(Arg(argc, argv, "--seed", "0"), &seed) ||
      !ParseF64(Arg(argc, argv, "--val-frac", "0.1"), &val_frac) ||
      !(val_frac >= 0.0 && val_frac < 1.0) ||
      !ParseF64(Arg(argc, argv, "--min-improvement", "0"), &min_improvement) ||
      !(min_improvement >= 0.0 && min_improvement < 1.0)) {
    std::fprintf(stderr, "invalid numeric argument\n");
    return 2;
  }
  const bool require_accuracy = Has(argc, argv, "--require-accuracy");
  const std::string report_path = Arg(argc, argv, "--report", "");
  // The peak the predicted step is computed against (S0 #146): the
  // compile's --peak-gflops, baked in, unless this run names another.
  double peak_gflops = kSeemlPeakGflops;
  if (const std::string p = Arg(argc, argv, "--peak-gflops", "");
      !p.empty() && (!ParseF64(p.c_str(), &peak_gflops) ||
                     !std::isfinite(peak_gflops) || !(peak_gflops > 0.0))) {
    std::fprintf(stderr, "invalid --peak-gflops\n");
    return 2;
  }
  // The best-state gate (E9): "auto" resolves inside the engine, against
  // the step count the run actually has (a resume knows its remainder).
  const std::string eval_every_text = Arg(argc, argv, "--eval-every", "auto");
  uint64_t eval_every = seeml::update_rt::TrainOptions::kEvalEveryAuto;
  uint64_t patience = 0;
  if ((eval_every_text != "auto" && !ParseU64(eval_every_text.c_str(), &eval_every)) ||
      !ParseU64(Arg(argc, argv, "--patience", "0"), &patience)) {
    std::fprintf(stderr, "invalid --eval-every / --patience\n");
    return 2;
  }
  if (patience > 0 && (eval_every == 0 || val_frac <= 0.0)) {
    std::fprintf(stderr,
                 "model_update: --patience needs periodic evaluation "
                 "(--eval-every > 0) and a validation split (--val-frac > 0)\n");
    return 2;
  }

  if (model.empty() || data.empty()) {
    std::fputs(kUsage, stderr);
    return 2;
  }

  // The pool width (#202 item 1): the flag wins over $SEEML_THREADS, which
  // the pool reads itself. Set before the plan loads and before the feeder
  // exists — the feeder decides at construction whether to spawn a thread.
  if (Has(argc, argv, "--threads")) {
    uint64_t threads = 0;
    if (!ParseU64(Arg(argc, argv, "--threads", ""), &threads) || threads == 0 ||
        threads > 4096) {
      std::fprintf(stderr, "invalid --threads (an integer from 1 to 4096)\n");
      return 2;
    }
    seeml::update::SetParallelThreadCount(static_cast<size_t>(threads));
  }

  // The executor backend: the flag wins over $SEEML_BACKEND, which wins
  // over the cpu default. Selected before the plan loads, so the load
  // binds the arena to the backend that will execute it.
  const char* backend_env = std::getenv("SEEML_BACKEND");
  const std::string backend_text =
      Arg(argc, argv, "--backend",
          backend_env && *backend_env ? backend_env : "cpu");
  const auto backend_kind =
      seeml::update_rt::ParseBackendKind(backend_text);
  if (!backend_kind) {
    std::fprintf(stderr,
                 "model_update: --backend (or $SEEML_BACKEND) must be cpu, "
                 "metal or auto, got '%s'\n",
                 backend_text.c_str());
    return 2;
  }
  // Where the plan is (#158): --plan names a file; otherwise the embedded
  // plan when this binary carries one, else update_plan.seeu beside the
  // executable — the disk-resident package mode, for plans the linker and
  // the loader cannot carry (above ~1.8 GB on macOS arm64).
  const bool embedded = kSeemlUpdatePlanSize > 0;
  const std::string plan_flag = Arg(argc, argv, "--plan", "");
  const std::string plan_path =
      !plan_flag.empty() ? plan_flag
      : embedded         ? std::string()
                         : ExecutableDir(argv[0]) + "/" + kPlanFileName;
  // The checkpoint flags, read here so the usage rules below can hold them
  // to the plan before anything loads. A resume is a checkpoint that is
  // there to resume: with --resume and no readable checkpoint — or one
  // bound to another plan, which the engine's load refuses — the engine
  // starts a fresh run ("no checkpoint resumed"), and the fresh run's rules
  // apply to it. Peeked once; the seed / split refusal below reads the same
  // record.
  const std::string checkpoint_path = Arg(argc, argv, "--checkpoint", "");
  const bool resume = Has(argc, argv, "--resume");
  uint64_t checkpoint_every = 0;
  if (!ParseU64(Arg(argc, argv, "--checkpoint-every", "0"),
                &checkpoint_every)) {
    std::fprintf(stderr, "invalid --checkpoint-every\n");
    return 2;
  }
  std::optional<seeml::update_rt::CheckpointRecord> resumed_from;
  if (resume && !checkpoint_path.empty())
    if (auto peek = seeml::update_rt::PeekCheckpointRecord(checkpoint_path))
      resumed_from = std::move(*peek);
  // --require-accuracy needs something to measure: class labels (the eval
  // program's softmax) and a validation split. The plan header is right
  // here in the embedded bytes (or the first bytes of the file), so the
  // usage error costs nothing — before any backend is built or the plan
  // hashed. A flag that cannot apply is a usage error, never a silently
  // vacuous gate. A plan file that cannot be opened fails closed here,
  // with the package mode spelled out.
  {
    seeml::update::PlanHeader hdr{};
    if (plan_path.empty()) {
      if (kSeemlUpdatePlanSize >= sizeof(hdr))
        std::memcpy(&hdr, kSeemlUpdatePlan, sizeof(hdr));
    } else {
      std::FILE* f = std::fopen(plan_path.c_str(), "rb");
      if (!f) {
        std::fprintf(stderr,
                     "load: cannot open the update plan '%s' (%s)%s\n",
                     plan_path.c_str(), std::strerror(errno),
                     plan_flag.empty()
                         ? "; this package carries no embedded plan — keep "
                           "update_plan.seeu beside model_update, or pass "
                           "--plan <file>"
                         : "");
        return 1;
      }
      const size_t got = std::fread(&hdr, 1, sizeof(hdr), f);
      std::fclose(f);
      if (got != sizeof(hdr)) {
        std::fprintf(stderr,
                     "load: '%s' is smaller than a plan header (%zu bytes)\n",
                     plan_path.c_str(), got);
        return 1;
      }
    }
    if (require_accuracy && (hdr.label_kind != 1 || val_frac <= 0.0)) {
      std::fprintf(stderr,
                   "model_update: --require-accuracy needs a class-label plan "
                   "and a validation split (--val-frac > 0)\n");
      return 2;
    }
    // The flags held to the plan by the recipe's rules (S4 #150): a --steps
    // inside the compiled warmup, a --checkpoint-every with no --checkpoint,
    // an --eval-every with no validation split — each was silently accepted.
    // Here with the other usage errors: the rules read the header and the
    // command line alone, so the refusal comes before the plan is hashed,
    // the model scanned or the corpus read. A validation split exists when
    // the plan compiled one or --val-frac asks for one.
    seeml::update::recipe::RunFlags flags;
    flags.steps_given = Has(argc, argv, "--steps");
    flags.steps = steps;
    // The checkpoint the engine will resume is one bound to THIS plan: a
    // stale file left by another (a recompiled package's) is refused by its
    // load as "a different plan" and the run starts fresh.
    flags.resume = resumed_from && resumed_from->step > 0 &&
                   resumed_from->plan_hash == hdr.plan_hash;
    flags.has_checkpoint_path = !checkpoint_path.empty();
    flags.checkpoint_every_given = Has(argc, argv, "--checkpoint-every");
    flags.checkpoint_every = checkpoint_every;
    flags.eval_every_given = eval_every_text != "auto";
    flags.eval_every = eval_every;
    flags.has_validation =
        (hdr.data_flags & seeml::update::kDataFlagSplit) != 0 || val_frac > 0.0;
    if (auto why = seeml::update::recipe::RunFlagsViolation(hdr, flags)) {
      std::fprintf(stderr, "model_update: %s\n", why->c_str());
      return 2;
    }
    // A checkpoint the engine will not resume binds this run to nothing.
    // The seed / split refusal below is a resume's: held against a stale
    // file — another plan's, which the engine's load refuses before it
    // starts fresh — it would exit 2 over "a different --seed" for a
    // checkpoint that never constrained this run, and only when the seeds
    // happen to differ.
    if (!flags.resume) resumed_from.reset();
  }

  seeml::update_rt::UpdateEngine engine;
  if (auto r = engine.SelectBackend(*backend_kind); !r) {
    std::fprintf(stderr, "backend: %s\n", r.error().c_str());
    return 1;
  }
  if (!engine.backend_note().empty())
    std::fprintf(stderr, "seeml-update: %s\n", engine.backend_note().c_str());
  const auto t_load0 = std::chrono::steady_clock::now();
  // Both routes hand the engine one (pointer, size) and run the same
  // validation — magic, version gate, the seal, both contracts — so a disk
  // plan is trusted exactly as much as an embedded one, and a swapped or
  // corrupt file is refused before anything executes.
  if (plan_path.empty()) {
    if (auto r = engine.LoadFromMemory(kSeemlUpdatePlan, kSeemlUpdatePlanSize);
        !r) {
      std::fprintf(stderr, "load: %s\n", r.error().c_str());
      return 1;
    }
    std::fprintf(stderr, "seeml-update: plan embedded (%zu bytes)\n",
                 kSeemlUpdatePlanSize);
  } else {
    if (auto r = engine.LoadFromFileMapped(plan_path); !r) {
      std::fprintf(stderr, "load: '%s': %s\n", plan_path.c_str(),
                   r.error().c_str());
      return 1;
    }
    std::fprintf(stderr, "seeml-update: plan from '%s' (%zu bytes, mapped%s)\n",
                 plan_path.c_str(), engine.plan_size(),
                 embedded ? "; the embedded plan is not used" : "");
  }
  // The backend is recorded wherever results are compared (the per-backend
  // determinism doctrine): the banner, the gate line below, and the report.
  std::fprintf(stderr, "seeml-update: backend %s (%s)\n",
               engine.backend_name(), engine.backend_device().c_str());

  // Fail fast: the plan's emit offsets are only meaningful inside the exact
  // file it was compiled from, and commit would refuse anyway — but only
  // after the full training run. One file scan here buys that refusal now.
  // A plan that scores what ships (E12, --quantize-base / --bf16-base from
  // a model file) also maps the file here: its eval program reads the f32
  // weights the commit will patch, so every gate score is the shipped one.
  if (auto r = engine.BindSourceModel(model); !r) {
    std::fprintf(stderr, "model: %s\n", r.error().c_str());
    return 1;
  }
  const double load_s = since(t_load0);  // plan + validation + source bind
  if (engine.scores_shipped())
    std::fprintf(stderr,
                 "seeml-update: validation scores the shipped model (the "
                 "f32 weights of '%s' plus the update)\n",
                 model.c_str());
  std::fprintf(stderr,
               "seeml-update: resource contract — arena %llu bytes"
               " (%llu persistent)\n",
               (unsigned long long)engine.header().arena_size,
               (unsigned long long)engine.header().persistent_size);

  const auto t_data0 = std::chrono::steady_clock::now();
  // --data: a pre-tokenized .sds, or raw text (#202 item 2) ingested here
  // with the model's own tokenizer.
  const std::string data_ext = DataExtension(data);
  auto dataset = data_ext == "txt" || data_ext == "jsonl"
                     ? LoadRawText(model, data, data_ext, engine.header())
                     : seeml::update_rt::Dataset::LoadFromFile(data);
  if (!dataset) {
    std::fprintf(stderr, "data: %s\n", dataset.error().c_str());
    return 1;
  }

  // Held-out validation split (before shuffling) drives the regression
  // gate. A plan that compiled its split (S3 #149, v22 kDataFlagSplit)
  // names the held-out records: the same function of (records, seed,
  // fraction) is recomputed here and its hash must be the plan's, so the
  // gate scores the set the compile decided; --val-frac is then not a
  // runner decision and is refused. Otherwise --val-frac splits by
  // position as before; 0 falls back to the training-loss trend.
  std::optional<seeml::update_rt::Dataset> val_set;
  const seeml::update::PlanHeader& plan_header = engine.header();
  if ((plan_header.data_flags & seeml::update::kDataFlagSplit) != 0) {
    if (Has(argc, argv, "--val-frac")) {
      std::fprintf(stderr,
                   "model_update: the plan compiled its validation split "
                   "(seed %llu, fraction %g); --val-frac is not a runner "
                   "decision for this plan\n",
                   (unsigned long long)plan_header.split_seed,
                   (double)seeml::update::ValFracOf(plan_header.val_frac_bits));
      return 2;
    }
    const std::vector<uint64_t> held = seeml::update::HeldOutIndices(
        dataset->num_samples(), plan_header.split_seed,
        seeml::update::ValFracOf(plan_header.val_frac_bits));
    const uint64_t split_hash = seeml::update::SplitHash(held);
    if (held.empty() || split_hash != plan_header.val_split_hash) {
      std::fprintf(stderr,
                   "data: the corpus does not yield the plan's compiled "
                   "split (%llu records; split hash %016llx, the plan's "
                   "%016llx): the plan was compiled over another corpus\n",
                   (unsigned long long)dataset->num_samples(),
                   (unsigned long long)split_hash,
                   (unsigned long long)plan_header.val_split_hash);
      return 1;
    }
    auto split = dataset->SplitHeldOut(held, split_hash);
    if (!split) {
      std::fprintf(stderr, "data: %s\n", split.error().c_str());
      return 1;
    }
    val_set = std::move(*split);
    val_frac = (double)seeml::update::ValFracOf(plan_header.val_frac_bits);
  } else if (val_frac > 0.0) {
    auto split = dataset->SplitValidation(val_frac);
    if (!split) {
      std::fprintf(stderr, "data: %s\n", split.error().c_str());
      return 1;
    }
    val_set = std::move(*split);
  }
  dataset->EnableShuffle(seed);
  const double data_s = since(t_data0);

  seeml::update_rt::TrainOptions options;
  options.checkpoint_path = checkpoint_path;
  options.resume = resume;
  options.validation = val_set ? &*val_set : nullptr;
  options.record_loss_curve = !loss_log.empty();
  options.eval_every = eval_every;
  options.patience = patience;
  options.checkpoint_every = checkpoint_every;
  // A resume is bound to the first run's shuffle seed and split (SEKP v5):
  // a different one would train on that run's validation rows. Refused
  // here as the usage error it is, before the engine loads anything; the
  // engine refuses again for callers that skip this check. (resumed_from
  // is set only for a checkpoint of this plan past step 0 — the engine's
  // own condition for holding the binding.)
  if (resumed_from && resumed_from->has_binding &&
      (resumed_from->shuffle_origin != dataset->shuffle_origin() ||
       resumed_from->train_samples != dataset->num_samples() ||
       resumed_from->val_samples != (val_set ? val_set->num_samples() : 0))) {
    std::fprintf(stderr,
                 "model_update: --resume refused: '%s' was written with a "
                 "different --seed or --val-frac (%llu train / %llu "
                 "validation samples); resume with the first run's "
                 "--seed and --val-frac\n",
                 options.checkpoint_path.c_str(),
                 (unsigned long long)resumed_from->train_samples,
                 (unsigned long long)resumed_from->val_samples);
    return 2;
  }

  options.should_stop = [] {
    return g_stop_requested.load(std::memory_order_acquire);
  };
  InstallStopHandlers();
  // The energy of the training run (#202 item 3), for the runtime screen.
  seeml::update_rt::EnergyMeter energy_meter;
  energy_meter.Start();
  const auto t_train0 = std::chrono::steady_clock::now();
  auto report = engine.Train(*dataset, steps, options);
  const double train_s = since(t_train0);
  const seeml::update_rt::EnergyReading energy = energy_meter.Stop();
  if (!report) {
    std::fprintf(stderr, "train: %s\n", report.error().c_str());
    return 1;
  }
  // A stopped run (#202 item 1) ran no bracketing evaluation: its end state
  // was never scored, so the report says so (null) rather than showing a
  // number nothing measured.
  const bool stopped = report->stopped_early;
  if (stopped) {
    const float none = std::numeric_limits<float>::quiet_NaN();
    report->val_final_loss = none;
    report->val_last_loss = none;
    report->val_final_accuracy = none;
    report->val_last_accuracy = none;
    std::fprintf(stderr,
                 "seeml-update: stopped by signal %d at step %llu%s\n",
                 g_stop_signal, (unsigned long long)engine.step(),
                 checkpoint_path.empty()
                     ? "; no --checkpoint, so nothing resumable was kept"
                     : "");
    if (!checkpoint_path.empty())
      std::fprintf(stderr,
                   "seeml-update: '%s' holds step %llu; rerun with --resume "
                   "to finish the run\n",
                   checkpoint_path.c_str(), (unsigned long long)engine.step());
  }
  std::fprintf(stderr, "seeml-update: train loss %.6f -> %.6f over %llu steps\n",
               report->initial_avg_loss, report->final_avg_loss,
               (unsigned long long)report->steps);
  if (report->has_validation && !stopped)
    std::fprintf(stderr,
                 "seeml-update: validation loss %.6f -> %.6f [backend %s]\n",
                 report->val_initial_loss, report->val_final_loss,
                 engine.backend_name());
  if (report->best_tracked && !stopped)
    std::fprintf(stderr,
                 "seeml-update: best state at step %llu (validation loss "
                 "%.6f); last state %.6f; %llu periodic evaluation(s)%s\n",
                 (unsigned long long)report->best_step, report->val_final_loss,
                 report->val_last_loss,
                 (unsigned long long)report->evaluations,
                 report->stopped_by_patience ? "; stopped: out of patience"
                                             : "");
  if (report->has_val_accuracy && !stopped)
    std::fprintf(stderr, "seeml-update: validation accuracy %.4f -> %.4f\n",
                 report->val_initial_accuracy, report->val_final_accuracy);

  // Every requested output is checked (CR4 #145 F66): a full disk used to
  // leave a truncated file and exit 0. A failed output after a commit is
  // exit 4 — the model is updated, the record is not — never a silent 0.
  bool outputs_ok = true;
  if (!loss_log.empty()) {
    std::FILE* f = std::fopen(loss_log.c_str(), "w");
    if (!f) {
      std::fprintf(stderr, "seeml-update: cannot write --loss-log '%s'\n",
                   loss_log.c_str());
      outputs_ok = false;
    } else {
      std::fprintf(f, "step,loss\n");
      for (size_t i = 0; i < report->loss_curve.size(); ++i)
        std::fprintf(f, "%zu,%.6f\n", i + 1, report->loss_curve[i]);
      const bool bad = std::ferror(f) != 0;
      if (std::fclose(f) != 0 || bad) {
        std::fprintf(stderr,
                     "seeml-update: failed writing --loss-log '%s'\n",
                     loss_log.c_str());
        outputs_ok = false;
      }
    }
  }

  // Regression gate: a failed update must leave the device untouched.
  // With a validation split this gates on held-out loss, not training
  // loss; --min-improvement demands a margin and --require-accuracy a
  // second, task-level opinion (#67). The verdict names the gate that
  // failed; the report is written last, so it records what actually
  // happened — including whether the commit landed.
  const bool loss_ok = report->ImprovedBy(static_cast<float>(min_improvement));
  const bool accuracy_measured = report->has_val_accuracy;
  const bool acc_ok =
      !require_accuracy || (accuracy_measured && report->AccuracyHeld());
  const bool accepted = loss_ok && acc_ok;
  // A stopped run is not weighed: the gate never sees a partial update.
  const char* verdict = stopped    ? "stopped"
                        : accepted ? "accepted"
                        : force    ? "forced"
                                   : "rejected";
  if (!stopped)
    std::fprintf(stderr,
                 "seeml-update: gate min-improvement %.4g require-accuracy %s"
                 " -> %s [backend %s]\n",
                 min_improvement, require_accuracy ? "yes" : "no", verdict,
                 engine.backend_name());

  // The runtime screen (S0 #146): the plan's own numbers — the memory the
  // device holds, the work of a step, the step the target peak predicts;
  // the rows the compile printed, recomputed here from the plan itself —
  // beside what this run measured. Printed after the gate, so the verdict
  // is in it, and carried by --report.
  seeml::update::Screen runtime_screen(seeml::update::kRuntimeScreen);
  {
    // On the GPU the prediction is against the GPU's stated peak, unless
    // this run named its own.
    if (std::string_view(engine.backend_name()).starts_with("metal") &&
        kSeemlGpuPeakGflops > 0.0 && !Has(argc, argv, "--peak-gflops"))
      peak_gflops = kSeemlGpuPeakGflops;
    // The rows themselves are the profiler's (S7 #153), shared with
    // seeml-bench: the plan's numbers beside what this run measured.
    std::optional<double> entropy;
    if (engine.header().label_kind == 1) entropy = dataset->LabelEntropyNats();
    seeml::update_rt::FillRuntimeScreen(runtime_screen, engine, *report,
                                        peak_gflops, verdict, entropy,
                                        &energy);
  }
  std::fputs(runtime_screen.Text(/*verbose=*/false).c_str(), stderr);
  double merge_s = 0.0, commit_s = 0.0;
  auto write_report = [&](bool committed, const char* error) {
    if (report_path.empty()) return;
    // Staged and renamed into place, every write checked: a truncated
    // report under the real name is worse than none (CR4 #145 F66).
    const std::string staged = report_path + ".tmp";
    std::FILE* f = std::fopen(staged.c_str(), "w");
    if (!f) {
      std::fprintf(stderr, "seeml-update: cannot write --report '%s'\n",
                   report_path.c_str());
      outputs_ok = false;
      return;
    }
    // JSON has no NaN/inf and no raw quotes: non-finite numbers become
    // null, strings are escaped.
    auto num = [&](float v) {
      if (std::isfinite(v)) std::fprintf(f, "%.8g", v);
      else std::fputs("null", f);
    };
    auto str = [&](const std::string& v) {
      std::fputc('"', f);
      for (char c : v) {
        if (c == '"' || c == '\\') std::fputc('\\', f);
        if (static_cast<unsigned char>(c) < 0x20) std::fputc(' ', f);
        else std::fputc(c, f);
      }
      std::fputc('"', f);
    };
    std::fputs("{\n  \"schema\": 3,\n  \"backend\": ", f);
    str(engine.backend_name());
    std::fputs(",\n  \"device\": ", f);
    str(engine.backend_device());
    // Which kernels this row measured (review F42): the instructions the
    // backend ran on a relaxed kernel (plan v18) — 0 on the reference
    // build, and for an exact plan, whatever the backend could do.
    std::fprintf(f, ",\n  \"relaxed_executions\": %llu",
                 (unsigned long long)engine.relaxed_executions());
    // The package mode (#158): the plan this run executed and where it
    // came from — the binary, or a file mapped at start-up.
    std::fputs(",\n  \"plan\": {\"source\": ", f);
    str(plan_path.empty() ? "embedded" : "file");
    std::fputs(", \"path\": ", f);
    if (plan_path.empty()) std::fputs("null", f);
    else str(plan_path);
    std::fprintf(f, ", \"bytes\": %zu}", engine.plan_size());
    std::fprintf(f, ",\n  \"steps\": %llu,\n  \"train_loss\": [",
                 (unsigned long long)report->steps);
    num(report->initial_avg_loss);
    std::fputs(", ", f);
    num(report->final_avg_loss);
    std::fputs("],\n", f);
    if (report->has_validation) {
      std::fputs("  \"validation_loss\": [", f);
      num(report->val_initial_loss);
      std::fputs(", ", f);
      num(report->val_final_loss);
      std::fputs("],\n", f);
    }
    // What the validation losses score (schema 3, E12): the model that
    // ships, or — for a narrow-storage plan compiled from memory — the
    // plan's own narrow weights, a proxy.
    std::fprintf(f, "  \"validation_scores\": \"%s\",\n",
                 engine.scores_shipped() ? "shipped" : "plan");
    if (report->best_tracked) {
      // validation_loss[1] above is the committed (best) state's; here is
      // the run's endpoint and where the best was found.
      std::fprintf(f,
                   "  \"best_state\": {\"step\": %llu, \"last_loss\": ",
                   (unsigned long long)report->best_step);
      num(report->val_last_loss);
      std::fprintf(f,
                   ", \"eval_every\": %llu, \"patience\": %llu, "
                   "\"evaluations\": %llu, \"stopped_by_patience\": %s},\n",
                   (unsigned long long)report->eval_every,
                   (unsigned long long)report->patience,
                   (unsigned long long)report->evaluations,
                   report->stopped_by_patience ? "true" : "false");
    }
    if (accuracy_measured) {
      std::fputs("  \"validation_accuracy\": [", f);
      num(report->val_initial_accuracy);
      std::fputs(", ", f);
      num(report->val_final_accuracy);
      std::fputs("],\n", f);
    }
    // Tier D: the lifecycle split — load and validate the plan (with the
    // source-model bind), the dataset, the training run with every
    // evaluation inside it (the two bracketing ones plus the periodic
    // ones), merge, commit, and the whole wall so far.
    std::fprintf(f,
                 "  \"lifecycle\": {\"load_s\": %.4f, \"data_s\": %.4f, "
                 "\"train_s\": %.4f, \"eval_s\": %.4f, \"evaluations\": %llu, "
                 "\"merge_s\": %.4f, \"commit_s\": %.4f, \"wall_s\": %.4f},\n",
                 load_s, data_s, train_s, report->eval_seconds,
                 (unsigned long long)(report->evaluations +
                                      (report->has_validation ? 2 : 0)),
                 merge_s, commit_s, since(t_main0));
    // The runtime screen, by key (S0 #146; the schema seeml-abi publishes).
    std::fprintf(f, "  \"runtime\": %s,\n", runtime_screen.Json(2).c_str());
    std::fprintf(f,
                 "  \"gate\": {\"min_improvement\": %.8g, "
                 "\"require_accuracy\": %s, \"loss_ok\": %s, "
                 "\"accuracy_measured\": %s, \"accuracy_ok\": %s, "
                 "\"forced\": %s},\n  \"verdict\": \"%s\",\n"
                 "  \"committed\": %s",
                 min_improvement, require_accuracy ? "true" : "false",
                 loss_ok ? "true" : "false",
                 accuracy_measured ? "true" : "false",
                 acc_ok ? "true" : "false",
                 (!accepted && force) ? "true" : "false", verdict,
                 committed ? "true" : "false");
    if (error) {
      std::fputs(",\n  \"error\": ", f);
      str(error);
    }
    std::fputs("\n}\n", f);
    const bool bad = std::ferror(f) != 0;
    if (std::fclose(f) != 0 || bad ||
        std::rename(staged.c_str(), report_path.c_str()) != 0) {
      std::fprintf(stderr, "seeml-update: failed writing --report '%s'\n",
                   report_path.c_str());
      std::remove(staged.c_str());
      outputs_ok = false;
    }
  };
  // Stopped before the gate, and before --force could matter: nothing is
  // merged or committed. Exit 5 — distinct from a failure (1) and from a
  // rejection (3), because the run is resumable, not wrong.
  if (stopped) {
    write_report(false, nullptr);
    return 5;
  }
  if (!accepted && !force) {
    const char* why =
        !loss_ok ? (report->has_validation
                        ? "validation loss did not improve by the required "
                          "margin"
                        : "training loss did not improve by the required "
                          "margin")
        : !accuracy_measured
            ? "validation accuracy was not measured (the eval program has "
              "no class-label softmax over the batch)"
            : "validation accuracy dropped";
    std::fprintf(stderr,
                 "seeml-update: REJECTED — %s; source model left untouched"
                 " (--force to override)\n",
                 why);
    write_report(false, nullptr);
    return 3;
  }

  const auto t_merge0 = std::chrono::steady_clock::now();
  if (auto r = engine.RunMerge(); !r) {
    std::fprintf(stderr, "merge: %s\n", r.error().c_str());
    write_report(false, r.error().c_str());
    return 1;
  }
  merge_s = since(t_merge0);
  const auto t_commit0 = std::chrono::steady_clock::now();
  if (auto r = engine.CommitToModel(model, out); !r) {
    std::fprintf(stderr, "commit: %s\n", r.error().c_str());
    write_report(false, r.error().c_str());
    return 1;
  }
  commit_s = since(t_commit0);
  write_report(true, nullptr);
  std::fprintf(stderr, "seeml-update: committed '%s'\n", out.c_str());
  // The committed model's report (S4 #150): it keeps the tokenizer section,
  // so compiling it again needs the report that describes these bytes.
  if (auto r = engine.WriteCommittedModelReport(out); !r) {
    std::fprintf(stderr, "seeml-update: the committed model's report: %s\n",
                 r.error().c_str());
    outputs_ok = false;
  }
  if (!outputs_ok) {
    std::fprintf(stderr,
                 "seeml-update: the update is committed, but a requested "
                 "output could not be written (exit 4)\n");
    return 4;
  }
  return 0;
}
